// Fictional example for code comparison.
async function checkout(order: Order) {
  const { sku, quantity } = order;
  const hold = await stock.reserve(sku, quantity);

  const payment = await pay(order);
  if (!payment.ok) {
    await stock.release(hold);
    await orders.fail(order.id, payment.reason);
    return { ok: false, reason: payment.reason };
  }

  await stock.commit(hold);
  await orders.confirm(order.id);
  return { ok: true, orderId: order.id };
}

